const handleDelete = async (agent: UnifiedAgent) => {
  if (!confirm(`Delete agent "${agent.name}" from ${agent.scopeLabel}?`)) return
  const key = agent.scope === 'global' ? `global-${agent.filename}` : `${agent.projectId}-${agent.filename}`
  setDeletingKeys((prev) => new Set(prev).add(key))
  try {
    if (agent.scope === 'global') {
      await deleteGlobalAgent(agent.filename)
    } else {
      await deleteProjectAgent(agent.projectId!, agent.filename)
    }
    refetch()
  } catch (err) {
    toast('error', err instanceof Error ? err.message : 'Failed to delete agent')
  } finally {
    setDeletingKeys((prev) => { const s = new Set(prev); s.delete(key); return s })
  }
}

const handleAction = async () => {
  if (!actionAgent || !actionType || !actionTarget) return
  setActioning(true)
  try {
    const from = actionAgent.scope === 'global' ? 'global' : actionAgent.projectId!
    const to = actionTarget
    if (actionType === 'copy') {
      await copyAgent(from, to, actionAgent.filename)
      toast('success', `Agent copied`)
    } else {
      await moveAgent(from, to, actionAgent.filename)
      toast('success', `Agent moved`)
    }
    setActionAgent(null)
    setActionType(null)
    setActionTarget('')
    refetch()
  } catch (err) {
    toast('error', err instanceof Error ? err.message : `Failed to ${actionType} agent`)
  } finally {
    setActioning(false)
  }
}

const handleCreate = async () => {
  if (!newName.trim()) return
  const slug = sanitizeName(newName)
  if (!slug) {
    toast('error', 'Invalid name — use letters, numbers, or hyphens')
    return
  }
  setCreateLoading(true)
  try {
    const template = `---\nname: ${newName.trim()}\ndescription: ""\nmodel: ""\n---\n\n# ${newName.trim()}\n\nWrite your agent instructions here.\n`
    if (createScope === 'global') {
      await updateGlobalAgent(slug, template)
      navigate(`/global/agents/${slug}`)
    } else {
      await updateProjectAgent(createScope, slug, template)
      navigate(`/projects/${createScope}/agents/${slug}`)
    }
    setCreating(false)
    setNewName('')
  } catch (err) {
    toast('error', err instanceof Error ? err.message : 'Failed to create agent')
  } finally {
    setCreateLoading(false)
  }
}

