710	// Topological sort helper
711	function topoSort(nodes, edges) {
712	  const inDegree = {};
713	  const adj = {};
714	  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
715	  for (const e of edges) {
716	    adj[e.source].push(e.target);
717	    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
718	  }
719	  const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
720	  const order = [];
721	  while (queue.length) {
722	    const id = queue.shift();
723	    order.push(id);
724	    for (const next of adj[id]) {
725	      inDegree[next]--;
726	      if (inDegree[next] === 0) queue.push(next);
727	    }
728	  }
729	  return order;
730	}
