733	  return new Promise((resolve, reject) => {
734	    const claudePath = process.env.CLAUDE_PATH || 'claude';
735	    const childEnv = { ...process.env, HOME: os.homedir() };
736	    delete childEnv.CLAUDECODE;
737	    const proc = spawn(claudePath, ['-p'], { env: childEnv });
738	    let out = '', err = '';
739	    proc.stdout.on('data', d => { out += d.toString(); });
740	    proc.stderr.on('data', d => { err += d.toString(); });
741	    proc.on('close', code => {
742	      if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
743	      else resolve(out.trim());
744	    });
