// --- Agent Orchestration ---
function loadOrchestrations() {
  try {
    if (fs.existsSync(ORCHESTRATIONS_PATH)) return JSON.parse(fs.readFileSync(ORCHESTRATIONS_PATH, 'utf-8'));
  } catch {}
  return [];
}

function saveOrchestrations(list) {
  fs.writeFileSync(ORCHESTRATIONS_PATH, JSON.stringify(list, null, 2));
}

app.get('/api/orchestrations', (req, res) => {
  res.json(loadOrchestrations());
});

app.post('/api/orchestrations', (req, res) => {
  const { id, name, nodes, edges } = req.body;
  if (!name || !Array.isArray(nodes) || !Array.isArray(edges)) {
    return res.status(400).json({ error: 'name, nodes, edges required' });
  }
  const list = loadOrchestrations();
  const now = new Date().toISOString();
  const orcId = id || genId();
  const idx = list.findIndex(o => o.id === orcId);
  const orc = { id: orcId, name, nodes, edges, updatedAt: now, createdAt: now };
  if (idx >= 0) { orc.createdAt = list[idx].createdAt; list[idx] = orc; }
  else list.unshift(orc);
  saveOrchestrations(list);
  res.json({ id: orcId });
});

app.delete('/api/orchestrations/:id', (req, res) => {
  saveOrchestrations(loadOrchestrations().filter(o => o.id !== req.params.id));
  res.json({ ok: true });
});

// Topological sort helper
function topoSort(nodes, edges) {
  const inDegree = {};
  const adj = {};
  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
  for (const e of edges) {
    adj[e.source].push(e.target);
    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
  }
  const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
  const order = [];
  while (queue.length) {
    const id = queue.shift();
    order.push(id);
    for (const next of adj[id]) {
      inDegree[next]--;
      if (inDegree[next] === 0) queue.push(next);
    }
  }
  return order;
}

function runClaudeSync(prompt) {
  return new Promise((resolve, reject) => {
    const claudePath = process.env.CLAUDE_PATH || 'claude';
    const childEnv = { ...process.env, HOME: os.homedir() };
    delete childEnv.CLAUDECODE;
    const proc = spawn(claudePath, ['-p'], { env: childEnv });
    let out = '', err = '';
    proc.stdout.on('data', d => { out += d.toString(); });
    proc.stderr.on('data', d => { err += d.toString(); });
    proc.on('close', code => {
      if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
      else resolve(out.trim());
    });
    proc.on('error', reject);
    proc.stdin.write(prompt, 'utf8');
    proc.stdin.end();
  });
}
